  jobSourceRun?: Prisma.JobSourceRunOmit;
  job?: Prisma.JobOmit;
  jobSourceRecord?: Prisma.JobSourceRecordOmit;
  jobMatch?: Prisma.JobMatchOmit;
  userJobState?: Prisma.UserJobStateOmit;
  generatedDocument?: Prisma.GeneratedDocumentOmit;
  application?: Prisma.ApplicationOmit;
  applicationEvent?: Prisma.ApplicationEventOmit;
  browserSession?: Prisma.BrowserSessionOmit;
  browserActionEvent?: Prisma.BrowserActionEventOmit;
  answerBankEntry?: Prisma.AnswerBankEntryOmit;
  notification?: Prisma.NotificationOmit;
  userConsent?: Prisma.UserConsentOmit;
  auditEvent?: Prisma.AuditEventOmit;
